0:
discovery.kubernetes "pods" {
  role = "pod"
}

discovery.relabel "add_metadata" {
  targets    = discovery.kubernetes.pods.targets
  rule {
    source_labels = ["__meta_kubernetes_namespace"]
    target_label = "namespace"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_container_image"]
    target_label = "image"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_name"]
    target_label = "pod"
  }
  rule {
    source_labels = ["__meta_kubernetes_pod_label_app_kubernetes_io_name"]
    target_label = "deployment"
  }
}

loki.source.kubernetes "pods" {
  targets    = discovery.relabel.add_metadata.output
  forward_to = [loki.write.grafana_cloud.receiver]
}

loki.write "grafana_cloud" {
  external_labels = {
    "cluster" = env("CLUSTER_ID"),
  }
  endpoint {
    url = env("GRAFANA_CLOUD_HOSTED_LOGS_URL")
    basic_auth {
      username = env("GRAFANA_CLOUD_HOSTED_LOGS_USER")
      password = env("GRAFANA_CLOUD_API_KEY")
    }
  }
}

1:
logging {
  level  = "info"
  format = "logfmt"
}

discovery.kubernetes "pods" {
  role = "pod"
}

loki.source.kubernetes "pods" {
  targets    = discovery.kubernetes.pods.targets
  forward_to = [loki.write.endpoint.receiver]
}

loki.write "endpoint" {
  endpoint {
      url = "http://loki-gateway.loki.svc.cluster.local:80/loki/api/v1/push"
      tenant_id = "local"
  }
}

# api_addr = "http://127.0.0.1:8200"
# cluster_addr = "https://127.0.0.1:8201"
ui = true

listener "tcp" {
  tls_disable = 1
  address = "[::]:8200"
  cluster_address = "[::]:8201"
  telemetry {
    unauthenticated_metrics_access = "true"
  }
}

seal "gcpckms" {
  disabled    = "false"
  project     = "techtales"
  region      = "europe-west3"
  key_ring    = "home-infra"
  crypto_key  = "vault-unseal"
}

# storage "file" {
#   path = "/openbao/data"
# }
storage "raft" {
  path = "/openbao/data"
}
service_registration "kubernetes" {}

0:
proxy_set_header Host $host;
proxy_set_header X-Real-IP $remote_addr;
proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
send_timeout 100m;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection "Upgrade";
